@startuml

enum RoomType {
  SINGLE
  DOUBLE
  TWIN
}

enum PaymentType {
  PREPAID
  PAID_AT_HOTEL
}

class HotelBookingManager {}

class Traveller {
  + name : string
  + reliabilityRating : int
}

class BillingInformation {
  + companyName : string
  + address : string
}

class TravelPreference {
  + preference : string
}

class Hotel {
  + city : string
  + address : string
}

class HotelChain {}

class RoomAvailability {
  + roomType : RoomType
  + isFullyBooked : boolean
}

class Offer {
  + price : float
}

class SpecialOffer extends Offer {}

class RegularOffer extends Offer {}

class Search {
  + city : string
  + arrivalDate : date
  + departureDate : date
  + numberOfRooms : int
  + roomType : RoomType
  + minimumRating : int
  + budgetPerNight : float
}

class Booking {
  + bookingId : string
  + cancellationDeadline : date
  + creditCardInformation : string
  + isConfirmed : boolean
  + isPrepaid : boolean
}

class PreliminaryBookingInfo {
  + price : float
  + cityArea : string
  + hotelRating : int
  + bookingId : string
}

