PreliminaryBookingInfo "*" -- "1" Hotel
PreliminaryBookingInfo "*" -- "1" Traveller
PreliminaryBookingInfo "*" -- "*" TravelPreference

SpecialOffer "*" -- "1" PreliminaryBookingInfo

@enduml

